import java.util.*;
public class Ocp {
    interface Shape { double area(); }
    static class Circle implements Shape {
        final double r; Circle(double r) { this.r = r; }
        public double area() { return Math.PI * r * r; }
    }
    static class Square implements Shape {
        final double a; Square(double a) { this.a = a; }
        public double area() { return a * a; }
    }
    static class Triangle implements Shape {
        final double b, h; Triangle(double b, double h) { this.b = b; this.h = h; }
        public double area() { return b * h / 2; }
    }
    public static void main(String[] args) {
        List<Shape> xs = List.of(new Circle(1), new Square(2), new Triangle(2, 3));
        System.out.println(xs.stream().mapToDouble(Shape::area).sum());
    }
}

