public class Singletons {
    static class Holder {
        private Holder() {}
        private static class H { static final Holder INSTANCE = new Holder(); }
        static Holder get() { return H.INSTANCE; }
    }
    static class Dcl {
        private static volatile Dcl instance;
        private Dcl() {}
        static Dcl get() {
            if (instance == null) {
                synchronized (Dcl.class) {
                    if (instance == null) instance = new Dcl();
                }
            }
            return instance;
        }
    }
    enum E { INSTANCE; void hi() { System.out.println("hi"); } }
    public static void main(String[] args) {
        System.out.println(Holder.get() == Holder.get());
        System.out.println(Dcl.get() == Dcl.get());
        E.INSTANCE.hi();
    }
}

public class FactoryMethod {
    interface Logger { void write(String msg); }
    static class ConsoleLogger implements Logger {
        public void write(String m) { System.out.println("console: " + m); }
    }
    static class FileLogger implements Logger {
        public void write(String m) { System.out.println("file: " + m); }
    }
    static abstract class LoggerFactory {
        abstract Logger create();
        void log(String m) { create().write(m); }
    }
    static class ConsoleFactory extends LoggerFactory {
        Logger create() { return new ConsoleLogger(); }
    }
    static class FileFactory extends LoggerFactory {
        Logger create() { return new FileLogger(); }
    }
    public static void main(String[] args) {
        new ConsoleFactory().log("hi");
        new FileFactory().log("hi");
    }
}

public class BuilderDemo {
    static class Computer {
        private final String cpu;
        private final int ram;
        private final int disk;
        private Computer(Builder b) { this.cpu = b.cpu; this.ram = b.ram; this.disk = b.disk; }
        public String toString() { return cpu + "/" + ram + "G/" + disk + "G"; }
        static class Builder {
            private String cpu = "default";
            private int ram = 8;
            private int disk = 256;
            Builder cpu(String c) { this.cpu = c; return this; }
            Builder ram(int r) { this.ram = r; return this; }
            Builder disk(int d) { this.disk = d; return this; }
            Computer build() {
                if (ram <= 0) throw new IllegalStateException("ram 必须为正");
                return new Computer(this);
            }
        }
    }
    public static void main(String[] args) {
        System.out.println(new Computer.Builder().cpu("i7").ram(16).build());
    }
}

import java.lang.reflect.*;
public class ProxyDemo {
    interface UserService { void save(String name); }
    static class RealUserService implements UserService {
        public void save(String name) { System.out.println("保存 " + name); }
    }
    public static void main(String[] args) {
        UserService real = new RealUserService();
        UserService proxy = (UserService) Proxy.newProxyInstance(
            UserService.class.getClassLoader(),
            new Class<?>[]{UserService.class},
            (p, m, a) -> {
                System.out.println("before " + m.getName());
                Object r = m.invoke(real, a);
                System.out.println("after");
                return r;
            });
        proxy.save("tom");
    }
}

public class DecoratorDemo {
    interface Coffee { int cost(); String desc(); }
    static class Espresso implements Coffee {
        public int cost() { return 10; }
        public String desc() { return "浓缩"; }
    }
    static abstract class AddOn implements Coffee {
        protected final Coffee inner;
        AddOn(Coffee c) { this.inner = c; }
    }
    static class Milk extends AddOn {
        Milk(Coffee c) { super(c); }
        public int cost() { return inner.cost() + 3; }
        public String desc() { return inner.desc() + "+牛奶"; }
    }
    static class Sugar extends AddOn {
        Sugar(Coffee c) { super(c); }
        public int cost() { return inner.cost() + 1; }
        public String desc() { return inner.desc() + "+糖"; }
    }
    public static void main(String[] args) {
        Coffee c = new Sugar(new Milk(new Espresso()));
        System.out.println(c.desc() + " " + c.cost());
    }
}

