import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
public class ObserverDemo {
    static class EventBus {
        private final List<java.util.function.Consumer<String>> hs = new CopyOnWriteArrayList<>();
        void on(java.util.function.Consumer<String> h) { hs.add(h); }
        void emit(String e) {
            for (var h : hs) {
                try { h.accept(e); } catch (RuntimeException ex) { System.out.println("观察者异常: " + ex.getMessage()); }
            }
        }
    }
    public static void main(String[] args) {
        EventBus bus = new EventBus();
        bus.on(e -> System.out.println("A 收到 " + e));
        bus.on(e -> { throw new IllegalStateException("B 坏了"); });
        bus.on(e -> System.out.println("C 收到 " + e));
        bus.emit("下单成功");
    }
}

