    }
}

// IS-A 成立：小概念 extends 大概念
class Instrument { }
class Guitar extends Instrument { }        // 吉他是一种乐器 ✓
class Employee extends Person { }          // 雇员是一种人 ✓（不是反过来）
class Jar extends Container { }            // 罐子是一种容器 ✓
class Titanium extends Metal { }           // 钛是一种金属 ✓

// IS-A 不成立：这些是 HAS-A 或方向反了
class Bathroom {
    Tub bathtub;                            // 浴室「拥有」浴缸，不是继承 ✓
    Sink theSink;
}
class Tub { int size; Bubbles b; }          // 浴缸「拥有」泡泡
// class Oven extends Kitchen { }           // 错：烤箱不是一种厨房
// class Ferrari extends Engine { }         // 错：法拉利「有」引擎
// class Person extends Employee { }        // 错：方向反了
// class Beverage extends Martini { }       // 错：方向反了

// 隔代 IS-A 也成立：
// Wolf extends Canine extends Animal → Wolf IS-A Animal ✓

// DO：柳树是一种树 → 继承合理
class Tree { void grow() { } }
class Willow extends Tree { }               // ✓ IS-A 成立

// DO：多个同类共享行为 → 上提到父类
class Shape {
    void rotate() { }                       // 公共行为只写一次
    void playSound() { }
}
class Square extends Shape { }
class Circle extends Shape { }              // ✓ 改 rotate 只改 Shape 一处

// DO NOT：为复用代码硬拉继承，IS-A 不过关
class Animal { void print() { } }
// class Potato extends Animal { }           // ✗ 马铃薯不是动物！

// 正确做法：用 HAS-A 组合一个 Printer
class Printer { void print() { } }
class Potato { Printer printer = new Printer(); }   // ✓ 拥有打印能力而非继承动物身份

// 决策卡四问：IS-A？共享所有子类行为？放父类合理？无更好替代？

// 问题设定：Dog/Cat 该有宠物行为，Hippo/Lion/Wolf 不该有
class Animal {
    void makeNoise() { }
    void eat() { }
    void sleep() { }
    void roam() { }
}
class Dog extends Animal { }      // 该有 beFriendly/play
class Cat extends Animal { }      // 该有 beFriendly/play
class Hippo extends Animal { }    // 不该有！河马不是宠物
class Lion extends Animal { }     // 不该有！

// 目标：PetShop 程序能写「面向宠物」的多态代码
// 形如：void playWithPet(宠物类型 p) { p.beFriendly(); p.play(); }
// 难点：这个「宠物类型」该是什么？
//   - 不能是 Animal（那样 Hippo/Lion 也被迫成宠物）
//   - 不能是 Dog 或 Cat（那样只能处理一种）
//   - 需要一个横跨 Dog/Cat、但不覆盖 Hippo/Lion 的「横向类型」

// 这就是「纵向继承树 + 横向能力」的错位，接口要解决的核心问题

// 方案一：把 pet 方法放进 Animal —— 污染所有动物
class Animal {
    void beFriendly() { /* 通用友好 */ }   // ✗ Hippo/Lion 也有！
    void play() { /* 通用玩耍 */ }
}
// 问题：河马、狮子、狼都有了宠物方法，语义荒唐且危险
// 且狗和猫的 pet 行为差异大，通用实现根本不合适

// 方案二：把 pet 方法放进 Animal 但改成抽象
abstract class Animal2 {
    abstract void beFriendly();
    abstract void play();
}
class Hippo extends Animal2 {
    void beFriendly() { }   // ✗ 被迫写空方法！
    void play() { }         // ✗ 非宠物却声明自己是宠物
}

// 两个方案的共同病根：
// 想用「纵向继承树」表达「横向的宠物能力」
// 放父类 → 污染所有子类
// 放某个子类 → 只覆盖一个分支
// 结论：需要一个不沿继承树分布的「横向类型」——接口

// 方案三：pet 方法只放 Dog/Cat —— 不污染，但丢了两样东西
class Dog extends Animal {
    void beFriendly() { }   // ✓ 只有宠物有
    void play() { }
}
class Cat extends Animal {
    void beFriendly() { }
    void play() { }
}
// Hippo/Lion 没有这些方法 —— 不污染，这点最好

// 问题1：协议没有支撑 —— 编译器查不了
// 有人把 beFriendly 写成 doFriendly、参数写错，编译器不会报错
// 因为没有任何类型在声明「宠物该有哪些方法」

// 问题2：失去多态 —— PetShop 代码必须认识每个宠物类
void playWith(Object x) {
    if (x instanceof Dog) ((Dog) x).beFriendly();   // 为 Dog 写分支
    else if (x instanceof Cat) ((Cat) x).beFriendly(); // 为 Cat 写分支
    // 每加一种宠物都要回来加分支！
}

// 真正需要的三条：
// ① 宠物行为只在宠物类（不污染）
// ② 有正式协议类型，编译器保证所有宠物方法一致
// ③ 能用协议类型多态，新增宠物不改旧代码
// → 这就是接口的设计目标

// 死亡菱形的经典结构
class DigitalRecorder {              // 顶端：共同祖先
    int i;
    void burn() { }
}
class CDBurner extends DigitalRecorder {
    @Override void burn() { }        // 覆盖：CD 刻录方式
}
class DVDBurner extends DigitalRecorder {
    @Override void burn() { }        // 覆盖：DVD 刻录方式
}
// Java 不允许下面这样（假设允许）：
// class ComboDrive extends CDBurner, DVDBurner { }
// 歧义1：combo.burn() 跑 CD 版还是 DVD 版？
// 歧义2：i 变量有几份、用 CDBurner 的还是 DVDBurner 的值？

// Java 的解法：单继承 + 多接口
// 一个类只能 extends 一个类（身份），但能 implements 多个接口（角色）
// 接口方法全抽象、无实例变量 → 没有冲突的实现和状态 → 绕开菱形

// 打油诗：
// Java 的家庭价值观：只有单亲！
// 父类定义「你是谁」，接口定义「你能演什么角色」

public abstract class Animal {
    // 抽象方法：没有方法体，分号结尾
    public abstract void makeNoise();
    public abstract void eat();

    // 具体方法：有方法体，子类可直接继承
    public void sleep() {
        System.out.println("通用睡觉");
    }
    public void roam() {
        System.out.println("通用游荡");
    }
}

// 对应规则：
// ① 有抽象方法的类必须标 abstract
// ② 抽象方法不能有方法体：public abstract void eat() { } 是错的
// ③ 抽象类可混合抽象方法与具体方法
// ④ private abstract void m() 非法（子类无法覆盖看不见的方法）

// 为什么需要：
// 声明「所有 Animal 子类型都有 makeNoise/eat」，但想不出通用实现
// → 为多态定义协议：Vet.giveShot(Animal a) 里可放心调 a.makeNoise()
// → 不用为 Lion、Wolf、Hippo 各写一个 giveShot 重载

public abstract class Animal {
    public abstract void makeNoise();   // 欠实现
    public abstract void eat();         // 欠实现
}

// 抽象子类可以「接一部分活」，把责任往下推
public abstract class Canine extends Animal {
    @Override public void eat() {       // Canine 实现了 eat，Dog 不用再写
        System.out.println("犬科通用吃法");
    }
    // makeNoise 还没实现，继续欠着
}

// 第一个具体类必须补齐所有剩下的抽象方法
public class Dog extends Canine {
    @Override public void makeNoise() { System.out.println("汪汪"); }  // 必须写
    // eat 已由 Canine 实现，不必再写
}

// 如果 Dog 忘了写 makeNoise，编译报错：
// Dog is not abstract and does not override abstract method makeNoise() in Animal

// 踢皮球规则：
// 抽象类可以把实现责任继续往下推（保持 abstract）
// 第一个具体类必须实现继承链上所有未实现的抽象方法
// 实现 = 写签名匹配、带方法体的方法（和覆盖动作一样）

abstract public class Canine extends Animal {
    public void roam() { }
}

public class MakeCanine {
    public void go() {
        Canine c;            // ✓ 可以：抽象类做引用类型
        c = new Dog();       // ✓ 可以：子类对象赋给父类引用（多态）
        // c = new Canine(); // ✗ 编译错误：Canine is abstract; cannot be instantiated
        c.roam();
    }
}

// 三句赋值的含义：
// Canine c;        → 抽象引用能用
// c = new Dog();   → 抽象引用能指向具体子类对象
// c = new Canine();// → 抽象类不能 new，编译器把关

// 抽象类的边界自测：
// abstract class A { }
// A a = new A();        ✗ 不能实例化
// A a;                  ✓ 声明引用
// A a = new B();        ✓ B extends A 且具体
// 抽象类可有实例变量、具体方法、构造器、静态成员
// 抽象类不能与 final 同时修饰（一个要被继承，一个禁止继承）
